package dev.halloween;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.client.option.Perspective;
final class LauncherCosmeticsChecks{
 static int age;static void register(){if(!Boolean.getBoolean("halloween.launcherCosmeticTest"))return;ClientTickEvents.END_CLIENT_TICK.register(c->{if(c.player==null||c.world==null)return;c.options.pauseOnLostFocus=false;c.options.hudHidden=true;if(c.currentScreen instanceof net.minecraft.client.gui.screen.GameMenuScreen)c.setScreen(null);age++;if(age==30){c.options.setPerspective(Perspective.THIRD_PERSON_FRONT);c.player.setPitch(0);c.player.setYaw(0);}
  if(age==50){try{var request=new com.google.gson.JsonObject();request.addProperty("id",java.util.UUID.randomUUID().toString());request.addProperty("createdAt",System.currentTimeMillis());request.addProperty("port",25579);request.addProperty("mode",Boolean.getBoolean("halloween.roomCheatsTest")?"adventure":"creative");request.addProperty("cheats",Boolean.getBoolean("halloween.roomCheatsTest"));java.nio.file.Files.writeString(net.fabricmc.loader.api.FabricLoader.getInstance().getConfigDir().resolve("villageplus-room-request.json"),request.toString());}catch(Exception e){throw new RuntimeException(e);}}
  if(age==150){try{for(int index=0;index<63;index++){var item=LauncherCosmeticsFeature.load(index);if(item==null||item.vertices().isEmpty())throw new AssertionError("catalog item failed: "+index);}if(LauncherCosmeticsClient.local.size()!=2)throw new AssertionError("launcher outfit not loaded");for(int id:LauncherCosmeticsClient.local){var mesh=LauncherCosmeticsFeature.load(id);if(mesh==null||mesh.vertices().isEmpty())throw new AssertionError("empty model "+id);}var wings=LauncherCosmeticsFeature.load(24);var first=LauncherCosmeticsFeature.poses(wings,0);var second=LauncherCosmeticsFeature.poses(wings,.7f);if(first.keySet().stream().noneMatch(name->!first.get(name).equals(second.get(name))))throw new AssertionError("animation did not move bones");if(c.getServer().getForcedGameMode()!=(Boolean.getBoolean("halloween.roomCheatsTest")?net.minecraft.world.GameMode.ADVENTURE:net.minecraft.world.GameMode.CREATIVE)||c.getServer().getPlayerManager().areCheatsAllowed()!=Boolean.getBoolean("halloween.roomCheatsTest"))throw new AssertionError("guest mode / cheats settings not applied");if(!c.getServer().isRemote()||c.getServer().getServerPort()!=25579)throw new AssertionError("room did not open on chosen port");org.slf4j.LoggerFactory.getLogger("launcher-cosmetic-test").info("PASS real keyframe animation changes bone transforms; launcher request opened world on chosen port 25579");net.minecraft.client.util.ScreenshotRecorder.saveScreenshot(c.runDirectory,"launcher-cosmetics.png",c.getFramebuffer(),1,t->{});org.slf4j.LoggerFactory.getLogger("launcher-cosmetic-test").info("PASS launcher config loaded, wing/hat assets parsed and actual third-person feature rendered; selected={}",LauncherCosmeticsClient.local);}catch(Throwable e){org.slf4j.LoggerFactory.getLogger("launcher-cosmetic-test").error("FAIL",e);}}
  if(age==170)c.scheduleStop();
 });}
}
